#include <pthread.h>
#include <semaphore.h>

#define N_PROCS 4
#define INCS    120

sem_t mutex;          /* 互斥信号量，初值 1 */
volatile int count = 0;

void *proc(void *arg) {
    for (int i = 0; i < INCS; i++) {
        sem_wait(&mutex);   /* P(mutex)：进入区 */
        count = count + 1;  /* 临界区：对共享变量累加 */
        sem_post(&mutex);   /* V(mutex)：退出区 */
    }
    return NULL;
}

int main(void) {
    sem_init(&mutex, 0, 1);
    pthread_t tid[N_PROCS];
    for (int i = 0; i < N_PROCS; i++)
        pthread_create(&tid[i], NULL, proc, NULL);
    for (int i = 0; i < N_PROCS; i++)
        pthread_join(tid[i], NULL);
    sem_destroy(&mutex);
    return 0;
}

